internal.body:
if (mode <= 0 || mode > MAX_MODE) {
  throw new fr.sorbonne_u.exceptions.PreconditionException("mode > 0 && mode <= MAX_MODE");
}
return 10.0 + (mode - 1) * 46.67;

if (mode <= 0 || mode > MAX_MODE) {
  throw new fr.sorbonne_u.exceptions.PreconditionException("mode > 0 && mode <= MAX_MODE");
}
return MAX_TEMP - (mode - 1) * (MAX_TEMP - MIN_TEMP) / (MAX_MODE - 1);

if (mode <= 0 || mode > MAX_MODE) {
  throw new fr.sorbonne_u.exceptions.PreconditionException("mode > 0 && mode <= MAX_MODE");
}
double targetTemp = computeTargetTemperature(mode);
fridge.setTargetTemperature(targetTemp);

upMode.body:
try {
  if (currentMode >= MAX_MODE) return false;
  setTemperatureByMode(currentMode + 1);
  currentMode++;
} catch(Exception e) {
  return false;
}
return true;

downMode.body:
try {
  if (currentMode <= 1) return false;
  setTemperatureByMode(currentMode - 1);
  currentMode--;
} catch(Exception e) {
  return false;
}
return true;

setMode.body:
try {
  if (modeIndex <= 0 || modeIndex > MAX_MODE) return false;
  setTemperatureByMode(modeIndex);
  currentMode = modeIndex;
} catch(Exception e) {
  return false;
}
return true;

suspend.body:
try {
  fridge.suspendCompressor();
  isSuspended = true;
} catch(Exception e) {
  return false;
}
return true;

resume.body:
try {
  fridge.resumeCompressor();
  setTemperatureByMode(currentMode);
  isSuspended = false;
} catch(Exception e) {
  return false;
}
return true;

emergency.body:
double currentTemp = fridge.getCurrentTemperature();
double targetTemp = fridge.getTargetTemperature();
double delta = java.lang.Math.abs(currentTemp - targetTemp);
if (delta > 3.0) return 1.0;
return delta / 3.0;
